<?php
require __DIR__.'/bootstrap.php';
requireAuth();
$error='';$items=[];$pdo=null;
try{
  $pdo=db();
  $q=trim((string)($_GET['q']??''));
  $mode=(string)($_GET['mode']??'');
  $sql="SELECT pv.id,pv.sku,pv.color_name,pv.stock_qty,pv.availability_mode,pv.lead_time,pv.is_active,pv.price_override,p.name product_name,p.id product_id,COALESCE(s.label,'Único') size_label FROM product_variants pv JOIN products p ON p.id=pv.product_id LEFT JOIN sizes s ON s.id=pv.size_id";
  $where=[];$params=[];
  if($q!==''){$where[]='(p.name LIKE ? OR pv.sku LIKE ? OR pv.color_name LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like];}
  if(in_array($mode,['stock','bajo_pedido'],true)){$where[]='pv.availability_mode=?';$params[]=$mode;}
  if($where)$sql.=' WHERE '.implode(' AND ',$where);
  $sql.=' ORDER BY p.name,pv.sort_order,pv.id LIMIT 300';
  $st=$pdo->prepare($sql);$st->execute($params);$items=$st->fetchAll();
}catch(Throwable $e){error_log('InYou inventario: '.$e->getMessage());$error='No se pudo cargar el inventario.';}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventario · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.wrap{max-width:1200px;margin:auto}.panel{background:#fff;border:1px solid #e7e5df;border-radius:12px;padding:22px;margin:20px 0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.input,.select{padding:11px;border:1px solid #d9d8d3;border-radius:7px;background:#fff}.input{min-width:280px}.btn{background:#202321;color:#fff;border:0;border-radius:7px;padding:11px 16px;text-decoration:none}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#f1f0eb;font-size:12px}.muted{color:#777}</style></head><body class="dashboard"><?php adminSidebar('inventory');?><main class="content"><div class="wrap"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?></div><form method="post" action="/admin/logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="signout">Cerrar sesión</button></form></header><div class="eyebrow">CATÁLOGO</div><h1>Inventario</h1><p>Vista central de variantes, stock y productos bajo pedido.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form class="toolbar" method="get"><input class="input" name="q" placeholder="Buscar producto, SKU o color" value="<?=h((string)($_GET['q']??''))?>"><select class="select" name="mode"><option value="">Todos los modos</option><option value="stock" <?=($_GET['mode']??'')==='stock'?'selected':''?>>Stock</option><option value="bajo_pedido" <?=($_GET['mode']??'')==='bajo_pedido'?'selected':''?>>Bajo pedido</option></select><button class="btn">Filtrar</button></form><section class="panel"><div style="overflow:auto"><table class="table"><thead><tr><th>Producto</th><th>SKU</th><th>Talle</th><th>Color</th><th>Disponibilidad</th><th>Stock</th><th>Plazo</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($items as $v):?><tr><td><strong><?=h($v['product_name'])?></strong></td><td><?=h($v['sku'])?></td><td><?=h($v['size_label'])?></td><td><?=h($v['color_name'])?></td><td><span class="badge"><?=h($v['availability_mode'])?></span></td><td><?=(int)$v['stock_qty']?></td><td><?=h($v['lead_time']?:'—')?></td><td><?=$v['is_active']?'Activa':'Inactiva'?></td><td><a href="/admin/variants.php?product=<?=(int)$v['product_id']?>&edit=<?=(int)$v['id']?>">Editar</a></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="9" class="muted">No hay variantes para mostrar.</td></tr><?php endif;?></tbody></table></div></section></div></main></body></html>